#!/usr/bin/env python3
"""OA Mock - local runner (Flipkart + Juspay + Amazon).

Run:  python3 oa_mock_local.py      (on Windows: python oa_mock_local.py)
It serves the mock test at http://127.0.0.1:8765 and compiles/runs your code
with the compilers on this computer: g++ (C++17), javac/java, and Python.
Needs Python 3.8+. Only listens on 127.0.0.1. Stop with Ctrl+C.
"""
import base64, glob, json, os, re, secrets, shutil, subprocess, sys, tempfile, time, webbrowser, zlib
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = int(os.environ.get("OA_PORT", "8765"))
TOKEN = secrets.token_hex(16)
PAGES = {k: zlib.decompress(base64.b64decode(v)).decode("utf-8") for k, v in json.loads(zlib.decompress(base64.b64decode(""))).items()}
TITLES = {"flipkart": "Flipkart OA Mock", "juspay": "Juspay OA Mock", "amazon": "Amazon OA Mock"}
IS_WIN = os.name == "nt"

def which(*names):
    for n in names:
        p = shutil.which(n)
        if p: return p
    return None

IS_MAC = sys.platform == "darwin"

# bits/stdc++.h for compilers that don't ship it (Apple clang on macOS)
SHIM_HEADERS = """#pragma once
#include <cassert>
#include <cctype>
#include <cfloat>
#include <climits>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <ctime>
#include <cstdint>
#include <algorithm>
#include <array>
#include <bitset>
#include <chrono>
#include <complex>
#include <deque>
#include <functional>
#include <iomanip>
#include <iostream>
#include <istream>
#include <iterator>
#include <limits>
#include <list>
#include <map>
#include <memory>
#include <numeric>
#include <optional>
#include <ostream>
#include <queue>
#include <random>
#include <set>
#include <sstream>
#include <stack>
#include <string>
#include <string_view>
#include <tuple>
#include <type_traits>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <variant>
#include <vector>
"""

def _version_key(path):
    m = re.search(r"(\d+)$", path)
    return int(m.group(1)) if m else 0

def find_cxx():
    """Prefer a real GCC (Homebrew g++-NN on macOS); fall back to g++/clang++."""
    cands = []
    for d in ("/opt/homebrew/bin", "/usr/local/bin", "/home/linuxbrew/.linuxbrew/bin"):
        cands += sorted(glob.glob(os.path.join(d, "g++-[0-9]*")), key=_version_key, reverse=True)
    for n in ["g++-%d" % v for v in range(16, 9, -1)] + ["g++", "clang++"]:
        p = shutil.which(n)
        if p: cands.append(p)
    for c in cands:
        try:
            v = subprocess.run([c, "--version"], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=20).stdout.decode("utf-8", "replace")
        except Exception:
            continue
        return c, ("clang" in v.lower() or "apple" in v.lower()), v.splitlines()[0] if v else c
    return None, False, ""

GPP, GPP_IS_CLANG, GPP_DESC = find_cxx()
SHIM_DIR = None
if GPP and GPP_IS_CLANG:
    SHIM_DIR = os.path.join(tempfile.gettempdir(), "oamock_shim")
    os.makedirs(os.path.join(SHIM_DIR, "bits"), exist_ok=True)
    with open(os.path.join(SHIM_DIR, "bits", "stdc++.h"), "w") as f: f.write(SHIM_HEADERS)

def cxx_args(src, exe):
    a = [GPP, "-std=c++17", "-O2"]
    if SHIM_DIR: a += ["-I", SHIM_DIR]
    if IS_MAC: a += ["-Wl,-stack_size,0x10000000"]   # 256 MB stack for deep recursion
    return a + ["-o", exe, src]
JAVAC, JAVA = which("javac"), which("java")
PY = sys.executable

def run_cmd(args, inp, limit_s, cwd):
    t = time.perf_counter()
    try:
        p = subprocess.run(args, input=inp.encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=limit_s, cwd=cwd)
        ms = (time.perf_counter() - t) * 1000
        out = p.stdout.decode("utf-8", "replace")
        err = p.stderr.decode("utf-8", "replace")
        if p.returncode != 0 and not err: err = "Process exited with code %d" % p.returncode
        elif p.returncode == 0: err = ""
        return {"out": out[:200000], "err": err[-4000:], "ms": ms, "tle": False}
    except subprocess.TimeoutExpired:
        return {"out": "", "err": "", "ms": limit_s * 1000, "tle": True}

def judge(lang, code, inputs, limit_ms):
    limit = max(0.5, min(limit_ms / 1000.0, 15))
    d = tempfile.mkdtemp(prefix="oamock_")
    try:
        if lang == "cpp":
            if not GPP: return {"compile_error": "No C++ compiler found. On macOS run: xcode-select --install  (or: brew install gcc). On Windows install MinGW-w64 and add g++ to PATH. Then restart this runner."}
            src = os.path.join(d, "main.cpp"); exe = os.path.join(d, "main.exe" if IS_WIN else "main")
            open(src, "w", encoding="utf-8").write(code)
            c = subprocess.run(cxx_args(src, exe), stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=90)
            if c.returncode != 0: return {"compile_error": c.stderr.decode("utf-8", "replace")[-6000:]}
            args = [exe]
        elif lang == "java":
            if not (JAVAC and JAVA): return {"compile_error": "javac/java were not found. Install a JDK and restart this runner."}
            open(os.path.join(d, "Main.java"), "w", encoding="utf-8").write(code)
            c = subprocess.run([JAVAC, "-encoding", "UTF-8", "Main.java"], cwd=d, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60)
            if c.returncode != 0: return {"compile_error": c.stderr.decode("utf-8", "replace")[-6000:]}
            args = [JAVA, "-Xss256m", "-cp", d, "Main"]
        elif lang == "py":
            open(os.path.join(d, "main.py"), "w", encoding="utf-8").write(code)
            args = [PY, "-X", "utf8", os.path.join(d, "main.py")]
        else:
            return {"compile_error": "Unsupported language: %s" % lang}
        return {"results": [run_cmd(args, i, limit, d) for i in inputs]}
    finally:
        shutil.rmtree(d, ignore_errors=True)

class H(BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def _host_ok(self):
        return self.headers.get("Host", "") in ("127.0.0.1:%d" % PORT, "localhost:%d" % PORT)
    def _send(self, code, body, ctype):
        b = body.encode("utf-8") if isinstance(body, str) else body
        self.send_response(code); self.send_header("Content-Type", ctype); self.send_header("Content-Length", str(len(b)))
        self.send_header("Cache-Control", "no-store"); self.end_headers(); self.wfile.write(b)
    def do_GET(self):
        if not self._host_ok(): return self._send(403, "forbidden", "text/plain")
        path = self.path.split("?")[0].strip("/")
        head = "<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'>" \
               "<style>:root{color-scheme:light}body{margin:0;font-size:14px}img{max-width:100%}[hidden]{display:none!important}</style>"
        if path in ("", "index.html"):
            links = "".join("<a href='/%s'>%s</a>" % (k, t) for k, t in TITLES.items())
            html = head + "<title>OA Mock</title><style>body{font:16px system-ui,sans-serif;background:#eef1f4;color:#18212b}main{max-width:560px;margin:60px auto;padding:0 16px}" \
                   "a{display:block;padding:18px 20px;margin:12px 0;background:#fff;border:1px solid #d6dde4;border-radius:10px;color:#1d6b5f;font-weight:600;text-decoration:none}a:hover{border-color:#1d6b5f}" \
                   "@media (prefers-color-scheme:dark){body{background:#0f151b;color:#e3e9ee}a{background:#161f27;border-color:#2a3743;color:#4fb7a4}}</style></head>" \
                   "<body><main><h1>OA Mock</h1><p>Pick a company. Your code compiles and runs on this computer.</p>" + links + "</main></body></html>"
            return self._send(200, html, "text/html; charset=utf-8")
        if path in PAGES:
            inject = "<script>window.LOCAL_JUDGE=true;window.LOCAL_TOKEN=%s;</script>" % json.dumps(TOKEN)
            return self._send(200, head + inject + "</head><body>" + PAGES[path] + "</body></html>", "text/html; charset=utf-8")
        self._send(404, "not found", "text/plain")
    def do_POST(self):
        if self.path != "/run" or not self._host_ok() or self.headers.get("X-Token") != TOKEN or "application/json" not in self.headers.get("Content-Type", ""):
            return self._send(403, '{"error":"forbidden"}', "application/json")
        try:
            n = int(self.headers.get("Content-Length", "0"))
            req = json.loads(self.rfile.read(n) or b"{}")
            res = judge(req.get("lang"), req.get("code", ""), list(req.get("inputs", []))[:50], float(req.get("limit", 2000)))
        except Exception as e:
            res = {"compile_error": "Runner error: %s" % e}
        self._send(200, json.dumps(res), "application/json")

def main():
    print("OA Mock - local runner (" + ", ".join(TITLES.values()) + ")")
    print("  C++  :", (GPP_DESC + ("  [bits/stdc++.h provided by the runner]" if SHIM_DIR else "")) if GPP else "NOT FOUND (macOS: xcode-select --install or brew install gcc)")
    print("  Java :", JAVAC or "NOT FOUND (install a JDK)")
    print("  Python:", PY)
    global PORT
    srv = None
    for p in range(PORT, PORT + 20):
        try:
            srv = ThreadingHTTPServer(("127.0.0.1", p), H); PORT = p; break
        except OSError:
            if p == PORT:
                print("\nPort %d is busy (an older runner may still be running; Ctrl+Z only pauses it." % p)
                print("Stop it with:  kill %%1   or   lsof -ti tcp:%d | xargs kill ). Trying another port..." % p)
    if srv is None:
        print("No free port between %d and %d." % (PORT, PORT + 19)); sys.exit(1)
    url = "http://127.0.0.1:%d/" % PORT
    print("\nOpen", url, "  (Ctrl+C to stop)")
    try: webbrowser.open(url)
    except Exception: pass
    try: srv.serve_forever()
    except KeyboardInterrupt: print("\nStopped.")

if __name__ == "__main__":
    main()
